  }
];

return MESSAGES.map(m => ({ json: m }));

// Normalise before anything reads the text.
// Alef and ya variants, Arabic-Indic digits, diacritics and tatweel all make
// the same word look like several different words to a matcher or a tokenizer.
const AR_DIGITS = { '٠':'0','١':'1','٢':'2','٣':'3','٤':'4',
                    '٥':'5','٦':'6','٧':'7','٨':'8','٩':'9' };

function normalise(text) {
  return text
    .replace(/[٠-٩]/g, d => AR_DIGITS[d])
    .replace(/[أإآ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/[ً-ْـ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map(item => {
  const raw = item.json.text || '';
  return { json: { ...item.json, raw_text: raw, text: normalise(raw) } };
});

