// The model's answer is a proposal, not a record.
// Unknown keys are rejected rather than dropped: a model inventing a field has
// misunderstood the contract, and silently discarding it hides the drift.
const ALLOWED = ['is_job_post','post_type','role','production_type',
  'location_canonical','location_raw','pay_amount','pay_currency','pay_unit',
  'shoot_date_raw','contact_raw','language_detected','confidence'];
const POST_TYPES = ['casting','crew','equipment','venue','other'];

// The HTTP node replaces the item with the response, so the message id is
// gone by here. Reach back to the node that still had it. This is the n8n
// idiom for carrying context past an HTTP call.
return items.map((item, i) => {
  const id = $('Normalise Arabic').all()[i].json.id;
  let parsed;
  try {
    parsed = JSON.parse(item.json.choices[0].message.content);
  } catch (e) {
    return { json: { id, valid: false, error: 'model did not return JSON' } };
  }
  const unknown = Object.keys(parsed).filter(k => !ALLOWED.includes(k));
  if (unknown.length) {
    return { json: { id, valid: false, error: 'unknown key(s): ' + unknown.join(', ') } };
  }
  if (typeof parsed.is_job_post !== 'boolean') {
    return { json: { id, valid: false, error: 'is_job_post must be boolean' } };
  }
  if (!POST_TYPES.includes(parsed.post_type)) {
    return { json: { id, valid: false, error: 'bad post_type: ' + parsed.post_type } };
  }
  if (parsed.pay_amount !== null && typeof parsed.pay_amount !== 'number') {
    return { json: { id, valid: false, error: 'pay_amount must be a number or null' } };
  }
  return { json: { id, valid: true, raw_text: item.json.raw_text, ...parsed } };
});
